def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    eric_prev = None
    strongest_prev = 0.0

    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((agent_id, opp))
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))
                if float(bid) > strongest_prev:
                    strongest_prev = float(bid)
            if agent_id == 'Eric' and bid is not None:
                eric_prev = float(bid)

    if not alive:
        return float(min(budget, 18.0))

    scarcity = 0.0
    if supply <= 16:
        scarcity = 1.0
    elif supply <= 18:
        scarcity = 0.7
    elif supply <= 21:
        scarcity = 0.4
    else:
        scarcity = 0.1

    danger = 0.0
    if hp <= 2 or no_water_days >= 2:
        danger = 1.0
    elif hp <= 4 or no_water_days >= 1:
        danger = 0.65
    elif hp <= 6:
        danger = 0.35
    else:
        danger = 0.1

    target = 22.0 + 18.0 * scarcity + 20.0 * danger

    if eric_prev is not None:
        if supply <= 18 or danger >= 0.65:
            target = max(target, eric_prev + 2.0)
        else:
            target = max(target, eric_prev * 0.72)
            if eric_prev >= 120:
                target -= 6.0
    elif strongest_prev > 0:
        target = max(target, strongest_prev * 0.8 + 1.0)

    living_count = len(alive)
    if living_count >= 3 and supply <= 17:
        target += 8.0
    elif living_count <= 1 and danger < 0.65:
        target -= 6.0

    if day >= 8:
        target += 8.0 * danger

    if budget < 80:
        target = min(target, budget * (0.72 if danger < 1.0 else 0.9))
    else:
        cap = budget * (0.55 + 0.3 * danger)
        target = min(target, cap)

    floor_bid = 8.0
    if danger >= 0.65:
        floor_bid = 20.0
    elif scarcity >= 0.7:
        floor_bid = 15.0

    bid = max(floor_bid, target)
    bid = min(bid, budget)
    if bid < 0:
        bid = 0.0
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    days_remaining = EPISODE_DAYS - day_context['day']
    urgency_multiplier = 1.0 + (day_context['day'] - 1) * 0.02

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

        if highest_prev_bid >= DAILY_SALARY * 0.85:
            if my_status['hp'] > 4 and days_remaining > 2:
                bid_value = highest_prev_bid + 2 
            else:
                bid_value = DAILY_SALARY * 0.98 
        else:
            base_bid_for_moderate = DAILY_SALARY * 0.6
            bid_value = max(base_bid_for_moderate, highest_prev_bid + 1.5)

            if day_context['supply'] <= WATER_REQ + 2:
                bid_value = max(bid_value, DAILY_SALARY * 0.75)

    else:
        if my_status['hp'] <= 3:
            bid_value = DAILY_SALARY * 0.9
        else:
            if day_context['supply'] <= WATER_REQ + 2:
                bid_value = DAILY_SALARY * 0.8
            else:
                bid_value = DAILY_SALARY * 0.65

    bid_value *= urgency_multiplier

    final_bid = min(my_status['budget'], bid_value)

    if final_bid <= 0.0 and my_status['hp'] < 10:
        final_bid = min(my_status['budget'], 1.0)

    return max(0.0, final_bid)

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 80
    WATER_REQ = 7
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(my_status['budget'], 20.0)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    avg_bid = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 80

    if my_status['hp'] < 4:
        bid = min(my_status['budget'], max(DAILY_SALARY * 1.2, avg_bid + 5))
    else:
        bid = min(my_status['budget'], max(DAILY_SALARY * 0.9, avg_bid * 0.9))

    return float(bid)
